<script setup lang="ts">
import { computed, inject, onBeforeUnmount, ref, watch, type Ref } from 'vue'
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import { useRoute, useRouter, onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router'
import { ArrowRight, Plus, Play, FlaskConical, Download, RotateCcw, X, Check, ShieldCheck, Pin } from '@lucide/vue'
import { api, post, percent, ms, pretty, human, type Project, type Report, type Execution, type Resource, type Version, type Obj, type User } from '@/api/client'
import { Button } from '@/components/ui/button'
import JsonView from '@/components/JsonView.vue'
import Status from '@/components/Status.vue'
import ResourceEditor from '@/components/ResourceEditor.vue'
import ModalFrame from '@/components/ModalFrame.vue'
import GateEditor from '@/components/GateEditor.vue'
import JsonField from '@/components/JsonField.vue'
import ImportedOutputEditor from '@/components/ImportedOutputEditor.vue'
import CriteriaSummary from '@/components/CriteriaSummary.vue'
import { caseLabel, criteriaSummary, metricLabel, releaseReason, suiteMetrics } from '@/lib/presentation'
const route = useRoute(), router = useRouter(), cache = useQueryClient()
const currentProject = inject<Ref<string>>('projectId')!
const currentUser = inject<Ref<User>>('user')!
const role = computed(() => currentUser.value?.workspaces.find(w => w.id === project.data.value?.workspace_id)?.role || 'viewer')
const canEdit = computed(() => role.value !== 'viewer')
const canAdmin = computed(() => role.value === 'owner')
const page = computed(() => route.params.executionId ? 'case' : route.params.experimentId ? 'results' : String(route.params.page || 'overview'))
const experimentId = computed(() => String(route.params.experimentId || ''))
const experiment = useQuery({ queryKey: computed(() => ['experiment', experimentId.value]), queryFn: () => api<Report>(`/experiments/${experimentId.value}`), enabled: computed(() => !!experimentId.value), refetchInterval: query => ['queued','running'].includes(query.state.data?.status || '') ? 2500 : false })
const projectId = computed(() => experimentId.value ? experiment.data.value?.project_id || '' : currentProject.value)
const project = useQuery({ queryKey: computed(() => ['project', projectId.value]), queryFn: () => api<Project>(`/projects/${projectId.value}`), enabled: computed(() => !!projectId.value), refetchInterval: 4000 })
const selectedVersion = ref(''), selectedResource = ref<Resource | null>(null)
const execution = useQuery({ queryKey: computed(() => ['execution', route.params.executionId]), queryFn: () => api<Execution>(`/executions/${route.params.executionId}`), enabled: computed(() => !!route.params.executionId) })
const reviewQueue = useQuery({ queryKey: computed(() => ['reviews', projectId.value]), queryFn: () => api<Execution[]>(`/projects/${projectId.value}/reviews`), enabled: computed(() => page.value === 'reviews' && !!projectId.value) })
const gateConfig = useQuery({ queryKey: computed(() => ['gate-config', projectId.value]), queryFn: () => api<Obj>(`/projects/${projectId.value}/gate`), enabled: computed(() => page.value === 'gates' && !!projectId.value) })
const settingsData = useQuery({ queryKey: computed(() => ['settings', projectId.value]), queryFn: async () => ({ credentials: await api<Obj[]>(`/projects/${projectId.value}/credentials`), tokens: await api<Obj[]>('/tokens'), audit: await api<Obj[]>(`/projects/${projectId.value}/audit`), members: await api<Obj[]>(`/workspaces/${project.data.value?.workspace_id}/members`) }), enabled: computed(() => page.value === 'settings' && !!project.data.value) })
const resources = (kind: string) => project.data.value?.resources.filter(r => r.kind === kind) || []
const versions = (kind: string) => resources(kind).flatMap(r => r.versions.map(v => ({ ...v, label: `${r.name} · v${v.number}` })))
const titles: Record<string,string> = { overview: 'Project overview', datasets: 'Datasets', targets: 'Targets', evaluators: 'Evaluators & suites', experiments: 'Experiments', reviews: 'Human review', gates: 'Release checks', settings: 'Project settings' }
const title = computed(() => page.value === 'results' ? experiment.data.value?.name || 'Experiment results' : page.value === 'case' ? caseLabel(execution.data.value?.case, execution.data.value?.case_id || 'Case detail') : titles[page.value] || 'Page not found')
const notice = ref(''), error = ref(''), busy = ref(false), modal = ref(''), formName = ref(''), editorKind = ref('dataset')
const datasetId = ref(''), targetId = ref(''), suiteId = ref(''), launchMode = ref('http'), repetitions = ref(1), concurrency = ref(2), budget = ref<number>(), launchName = ref(''), imported = ref('[]')
const gateExperiment = ref(''), metric = ref('record_exact')
const reviewMetric = ref(''), reviewNote = ref(''), reviewPassed = ref(false), onlyUnreviewed = ref(true)
const secretName = ref(''), secretValue = ref(''), tokenName = ref('CI pipeline'), newToken = ref(''), member = ref({ email: '', name: '', password: '', role: 'viewer' })
const openaiValue = ref('')
watch(projectId, () => { openaiValue.value = ''; secretValue.value = '' })
const openaiCredential = computed(() => settingsData.data.value?.credentials.find(c => c.name === 'OpenAI'))
const serviceCredentials = computed(() => settingsData.data.value?.credentials.filter(c => c.id !== openaiCredential.value?.id) || [])
const showServiceCredentials = computed(() => !!settingsData.data.value && (
  openaiCredential.value?.source !== 'environment' || serviceCredentials.value.length > 0 ||
  resources('target').some(r => r.versions.some(v => v.config.kind !== 'openai'))
))
const launchCredentials = useQuery({ queryKey: computed(() => ['credentials', projectId.value]), queryFn: () => api<Obj[]>(`/projects/${projectId.value}/credentials`), enabled: computed(() => modal.value === 'launch' && !!projectId.value), staleTime: 0 })
const launchJudges = computed(() => {
  const ids = versions('suite').find(v => v.id === suiteId.value)?.config.evaluator_version_ids || []
  return versions('evaluator').filter(v => ids.includes(v.id) && v.config.kind === 'llm_judge' && v.config.config.mode === 'live')
})
const launchCredentialIssue = computed(() => {
  const ids = launchJudges.value.map(v => v.config.config.credential_id)
  if (launchMode.value === 'http') { const id = versions('target').find(v => v.id === targetId.value)?.config.credential_id; if (id) ids.push(id) }
  if (!ids.length) return ''
  if (launchCredentials.isFetching.value) return 'Checking credentials…'
  if (launchCredentials.error.value) return 'Unable to check credentials. Reopen this dialog to retry.'
  const missing = ids.find(id => !launchCredentials.data.value?.some(c => c.id === id && c.configured))
  if (!missing) return ''
  return launchCredentials.data.value?.find(c => c.id === missing)?.source === 'environment' ? 'Set OPENAI_API_KEY in the server .env before launching.' : 'Add your API key in Settings to run this experiment.'
})
const testResult = ref<Obj | null>(null), filter = ref('all')
const latestId = computed(() => project.data.value?.experiments.find(e => e.status === 'completed')?.id || '')
const latest = useQuery({ queryKey: computed(() => ['latest', latestId.value]), queryFn: () => api<Report>(`/experiments/${latestId.value}`), enabled: computed(() => page.value === 'overview' && !!latestId.value) })
const queryError = computed(() => [project.error.value, experiment.error.value, execution.error.value, reviewQueue.error.value, gateConfig.error.value, settingsData.error.value].find(Boolean))
const displayReviews = computed(() => reviewQueue.data.value?.filter(r => (!onlyUnreviewed.value || !r.reviews.length) && (!reviewSearch.value || `${r.case_id} ${caseLabel(r.case, r.case_id)} ${r.experiment_name}`.toLowerCase().includes(reviewSearch.value.toLowerCase()))) || [])
const filteredRows = computed(() => experiment.data.value?.executions.filter(r => filter.value === 'all' || (filter.value === 'failing' ? r.results.some(e => e.passed === false) : r.status !== 'completed')) || [])
const resourceSearch = ref(''), experimentSearch = ref(''), experimentStatus = ref(''), reviewSearch = ref('')
const workspaceTokens = computed(() => settingsData.data.value?.tokens.filter(t => t.workspace_id === project.data.value?.workspace_id) || [])
const tokenScope = ref('read'), tokenDays = ref(30), copied = ref(false)
const metricKeys = computed(() => [...new Set(versions('evaluator').map(v => String(v.config.metric_key)))])
const gateMetrics = computed(() => suiteMetrics(project.data.value, project.data.value?.experiments.find(e => e.id === gateExperiment.value)))
watch(gateMetrics, keys => { if (!keys.includes(metric.value)) metric.value = keys.includes('record_exact') ? 'record_exact' : keys[0] || '' })
const gateReady = computed(() => !!gateExperiment.value && !!metric.value && !['queued', 'running'].includes(project.data.value?.experiments.find(e => e.id === gateExperiment.value)?.status || 'queued'))
const gateCheck = useQuery({ queryKey: computed(() => ['release-check', gateExperiment.value, metric.value, gateConfig.data.value]), queryFn: () => api<Obj>(`/experiments/${gateExperiment.value}/gate?metric=${encodeURIComponent(metric.value)}`), enabled: computed(() => page.value === 'gates' && gateReady.value) })
const gateResult = gateCheck.data
const resultMetricCount = computed(() => Object.keys(experiment.data.value?.summary.metrics || {}).length)
const passingCases = computed(() => experiment.data.value?.executions.filter(e => e.status === 'completed' && resultMetricCount.value > 0 && criteriaSummary(e.results, resultMetricCount.value).passed === resultMetricCount.value).length || 0)
const resultCoverage = computed(() => { const total = (experiment.data.value?.summary.total || 0) * resultMetricCount.value; return total ? experiment.data.value!.executions.reduce((n,e) => n + e.results.filter(r => r.status === 'scored').length, 0) / total : null })
const hasScoreIssues = computed(() => Object.values(experiment.data.value?.summary.metrics || {}).some(m => (m as Obj).not_applicable || (m as Obj).errors || (m as Obj).missing))
const overviewMetric = computed(() => Object.keys(latest.data.value?.summary.metrics || {}).find(k => k === 'field_accuracy') || Object.keys(latest.data.value?.summary.metrics || {})[0] || '')
const visibleExperiments = computed(() => (project.data.value?.experiments || []).filter(e => (!experimentStatus.value || e.status === experimentStatus.value) && e.name.toLowerCase().includes(experimentSearch.value.toLowerCase())))
const visibleResources = (kind: string) => resources(kind).filter(r => r.name.toLowerCase().includes(resourceSearch.value.toLowerCase()))
const baselineLabel = computed(() => { const b = project.data.value?.baselines.find(b => b.name === 'main'); return project.data.value?.experiments.find(e => e.id === b?.experiment_id)?.name || (b ? b.experiment_id.slice(0,8) : 'No baseline pinned yet') })
const hasImportedOutputs = computed(() => !!project.data.value?.experiments.some(e => e.mode === 'imported' && ['completed', 'partially_failed'].includes(e.status)))
const readiness = computed(() => [
 { label: 'Create a dataset', hint: 'Define inputs and expected behavior.', key: 'datasets', done: !!versions('dataset').length },
 { label: 'Provide outputs', hint: hasImportedOutputs.value ? 'Saved outputs are ready to evaluate.' : 'Configure a target or import saved outputs.', key: hasImportedOutputs.value ? 'experiments' : 'targets', done: hasImportedOutputs.value || !!versions('target').length },
 { label: 'Build an evaluation suite', hint: 'Select and pin the criteria for a run.', key: 'evaluators', done: !!versions('suite').length },
 { label: 'Run and pin a baseline', hint: 'Capture the reference for future comparisons.', key: 'experiments', done: !!project.data.value?.baselines.length },
])
const progress = computed(() => { const all = experiment.data.value?.executions || []; const done = all.filter(e => !['queued', 'running'].includes(e.status)).length; return { done, total: all.length, percent: all.length ? done / all.length * 100 : 0 } })
const launchDataset = useQuery({ queryKey: computed(() => ['launch-dataset', datasetId.value]), queryFn: () => api<Version & { cases: Obj[] }>(`/versions/${datasetId.value}`), enabled: computed(() => modal.value === 'launch' && !!datasetId.value) })
const plannedCalls = computed(() => (launchDataset.data.value?.cases.length || 0) * Number(repetitions.value))
const launchMissing = computed(() => !datasetId.value ? 'Create a dataset before starting a run.' : !suiteId.value ? 'Create an evaluation suite before starting a run.' : launchMode.value === 'http' && !targetId.value ? 'Configure a target, or choose imported outputs.' : '')
watch(launchMode, () => { launchValid.value = true })
const launchValid = ref(true), testValid = ref(true), testJson = ref<unknown>({})
const launchSnapshot = () => JSON.stringify([launchName.value,datasetId.value,targetId.value,suiteId.value,launchMode.value,repetitions.value,concurrency.value,budget.value,imported.value])
let originalLaunch = ''
function closeModal() { if (busy.value) return; if (modal.value === 'launch' && originalLaunch !== launchSnapshot() && !window.confirm('Discard this experiment draft?')) return; modal.value = ''; error.value = '' }
const guardLaunch = () => modal.value !== 'launch' || originalLaunch === launchSnapshot() || window.confirm('Leave without launching this experiment?')
onBeforeRouteLeave(guardLaunch)
onBeforeRouteUpdate(guardLaunch)
function unloadDraft(event: BeforeUnloadEvent) { if (modal.value === 'launch' && originalLaunch !== launchSnapshot()) { event.preventDefault(); event.returnValue = '' } }
window.addEventListener('beforeunload', unloadDraft)
onBeforeUnmount(() => window.removeEventListener('beforeunload', unloadDraft))
async function resourceSaved() { modal.value = ''; notice.value = 'Immutable version saved'; await cache.invalidateQueries() }
async function copyToken() { try { await navigator.clipboard.writeText(newToken.value); copied.value = true } catch { error.value = 'Clipboard is unavailable. Select and copy the token manually.' } }
let formProject = ''
watch(() => project.data.value, p => { if (p) { if (!metricKeys.value.includes(metric.value)) metric.value = metricKeys.value[0] || '';  if (formProject !== p.id) { datasetId.value = ''; targetId.value = ''; suiteId.value = ''; gateExperiment.value = ''; launchMode.value = versions('target').length ? 'http' : 'imported'; imported.value = '[]'; formProject = p.id }; datasetId.value ||= versions('dataset').find(v => !v.config.held_out)?.id || versions('dataset')[0]?.id || ''; targetId.value ||= versions('target')[0]?.id || ''; suiteId.value ||= versions('suite').find(v => v.label.includes('Release'))?.id || versions('suite')[0]?.id || ''; gateExperiment.value ||= p.experiments.find(e => e.id === route.query.experiment)?.id || p.experiments[0]?.id || '' } }, { immediate: true })
watch(modal, value => { if (value === 'launch') originalLaunch = launchSnapshot(); if (value) error.value = '' })
watch(() => execution.data.value, v => { if (v) reviewMetric.value = v.results[0]?.metric_key || '' })
async function action(fn: () => Promise<unknown>, message = 'Saved') { busy.value = true; error.value = ''; try { await fn(); notice.value = message; await cache.invalidateQueries() } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
function openCreate(kind: string) { selectedResource.value = null; editorKind.value = kind; modal.value = 'resource'; error.value = '' }
function openEdit(r: Resource) { selectedResource.value = r; editorKind.value = r.kind; modal.value = 'resource'; error.value = '' }
async function launchExperiment() { await action(async () => { const result = await post<Report>(`/projects/${projectId.value}/experiments`, { name: launchName.value || `Experiment ${new Date().toLocaleString('en-US')}`, dataset_version_id: datasetId.value, target_version_id: launchMode.value === 'http' ? targetId.value : null, suite_version_id: suiteId.value, repetitions: Number(repetitions.value), concurrency: Number(concurrency.value), mode: launchMode.value, imports: launchMode.value === 'imported' ? JSON.parse(imported.value) : [], import_dataset_version_id: launchMode.value === 'imported' ? datasetId.value : null, max_target_calls: budget.value || null }); modal.value = ''; router.push(`/experiments/${result.id}`) }, 'Experiment queued') }
async function rescore() { await action(async () => { const e = experiment.data.value!; const r = await post<Report>(`/experiments/${e.id}/rescore`, { suite_version_id: suiteId.value || e.suite_version_id, name: `${e.name} · rescore` }); router.push(`/experiments/${r.id}`) }, 'Saved outputs queued for rescoring') }
async function saveReview() { await action(async () => { await post(`/executions/${route.params.executionId}/reviews`, { metric_key: reviewMetric.value, passed: reviewPassed.value, note: reviewNote.value }); reviewNote.value = '' }, 'Human assessment saved; automated result preserved') }
async function saveOpenaiKey() { await action(async () => { await api(`/projects/${projectId.value}/credentials/${openaiCredential.value!.id}`, { method: 'PUT', body: JSON.stringify({ value: openaiValue.value }) }); openaiValue.value = '' }, 'API key saved') }
async function createSecret() { await action(async () => { await post(`/projects/${projectId.value}/credentials`, { name: secretName.value, value: secretValue.value }); secretValue.value = '' }, 'Encrypted credential saved') }
async function createToken() { await action(async () => { const r = await post<Obj>('/tokens', { workspace_id: project.data.value?.workspace_id, name: tokenName.value, scopes: tokenScope.value === 'write' ? ['read','write'] : ['read'], days: Number(tokenDays.value) }); newToken.value = r.token; copied.value = false }, 'Token created; copy it now') }
</script>
<template>
<main id="main-content" class="content" tabindex="-1">
  <RouterLink v-if="page === 'case' || page === 'results'" :to="page === 'case' && execution.data.value?.experiment_id ? `/experiments/${execution.data.value.experiment_id}` : `/projects/${projectId}/experiments`" class="back-link">← {{ page === 'case' ? 'Back to experiment' : 'All experiments' }}</RouterLink><div class="page-heading"><div><h1>{{ title }}</h1></div><div class="heading-actions"><span v-if="project.data.value?.fixture" class="fixture-chip">Deterministic fixtures</span><Button v-if="canEdit && ['overview','experiments'].includes(page)" @click="modal = 'launch'"><Plus :size="16"/>New experiment</Button><Button v-if="canEdit && ['datasets','targets','evaluators'].includes(page)" @click="openCreate(page === 'datasets' ? 'dataset' : page === 'targets' ? 'target' : 'evaluator')"><Plus :size="16"/>{{ page === 'datasets' ? 'New dataset' : page === 'targets' ? 'New target' : 'New evaluator' }}</Button></div></div>
  <div v-if="!canEdit && project.data.value" class="info-strip">Viewer access. You can inspect and export results; editing requires an editor or owner.</div><div v-if="error || queryError" class="error" role="alert">{{ error || (queryError as Error)?.message }}</div><div v-if="notice" class="notice" role="status"><Check :size="15"/>{{ notice }}<button aria-label="Dismiss notification" @click="notice = ''"><X :size="14"/></button></div>
  <div v-if="!titles[page] && !['results','case'].includes(page)" class="empty-state panel"><h3>This page does not exist</h3><RouterLink :to="`/projects/${projectId}/overview`" class="text-link">Back to overview</RouterLink></div><div v-if="project.isPending.value && projectId" class="empty-state"><h3>Loading your project…</h3></div>
  <template v-else-if="page === 'overview'">
    <div class="overview-actions"><span class="baseline-summary"><strong>Baseline</strong> {{ baselineLabel }}</span><div><RouterLink :to="`/projects/${projectId}/compare`" class="text-link">Compare runs <ArrowRight :size="15"/></RouterLink><RouterLink :to="`/projects/${projectId}/reviews`" class="text-link">Review cases</RouterLink></div></div>
    <div class="stat-grid"><article class="stat-card"><span>Experiments</span><strong>{{ project.data.value?.experiments.length || 0 }}</strong></article><article class="stat-card"><span>Dataset versions</span><strong>{{ versions('dataset').length }}</strong></article><article class="stat-card"><span>Latest {{ overviewMetric ? overviewMetric.replaceAll('_', ' ') : 'score' }}</span><strong>{{ percent(latest.data.value?.summary.metrics[overviewMetric]?.mean) }}</strong><small>{{ latest.data.value?.summary.metrics[overviewMetric]?.scored || 0 }} / {{ latest.data.value?.summary.total || 0 }} cases scored</small></article><article class="stat-card"><span>Latest coverage</span><strong>{{ percent(latest.data.value?.summary.metrics[overviewMetric]?.coverage) }}</strong><small>{{ latest.data.value?.summary.target_errors || 0 }} target errors</small></article></div>
    <p v-if="latest.data.value" class="latest-context">Latest result: <RouterLink :to="`/experiments/${latestId}`" class="text-link">{{ latest.data.value.name }}</RouterLink></p>
    <div v-if="readiness.some(step => !step.done)" class="setup-checklist"><RouterLink v-for="(step, i) in readiness" :key="step.key" :to="`/projects/${projectId}/${step.key}`" :class="{ done: step.done }"><span class="step-number"><Check v-if="step.done" :size="16"/><template v-else>{{ i + 1 }}</template></span><span><strong>{{ step.label }}</strong><small>{{ step.hint }}</small></span><ArrowRight :size="15"/></RouterLink></div>
  </template>
  <section v-if="['overview','experiments'].includes(page)" class="panel"><div class="panel-header"><h2>{{ page === 'overview' ? 'Recent experiments' : 'Run history' }} <span class="count">{{ project.data.value?.experiments.length || 0 }}</span></h2><RouterLink v-if="page === 'overview'" :to="`/projects/${projectId}/experiments`" class="text-link">View all <ArrowRight :size="14"/></RouterLink></div><div v-if="page === 'experiments'" class="table-toolbar"><input v-model="experimentSearch" aria-label="Search experiments" placeholder="Search experiments…"/><select v-model="experimentStatus" aria-label="Filter experiment status"><option value="">All statuses</option><option v-for="status in ['queued','running','completed','partially_failed','failed','canceled']" :key="status" :value="status">{{ human(status) }}</option></select><small>{{ visibleExperiments.length }} matching</small></div><table v-if="visibleExperiments.length"><thead><tr><th>Experiment</th><th>Status</th><th v-if="page !== 'overview'">Mode</th><th v-if="page !== 'overview'">Concurrency</th><th>Created</th></tr></thead><tbody><tr v-for="e in visibleExperiments.slice(0,page === 'overview' ? 6 : 100)" :key="e.id"><td><RouterLink :to="`/experiments/${e.id}`" class="strong-link">{{ e.name }}</RouterLink><small v-if="page !== 'overview'" class="block mono">{{ e.id.slice(0,8) }}</small></td><td><Status :value="e.status"/></td><td v-if="page !== 'overview'">{{ e.parent_id ? 'Rescored outputs' : e.mode === 'imported' ? 'Imported outputs' : 'Live target' }}</td><td v-if="page !== 'overview'">{{ e.concurrency }}</td><td class="muted" :title="new Date(e.created_at).toLocaleString('en-US')">{{ page === 'overview' ? new Date(e.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : new Date(e.created_at).toLocaleString('en-US') }}</td></tr></tbody></table><div v-else class="empty-state"><FlaskConical/><h3>{{ experimentSearch || experimentStatus ? 'No experiments match' : 'Your first experiment starts here' }}</h3><p>{{ experimentSearch || experimentStatus ? 'Try another search or clear the status filter.' : 'Select a dataset and evaluation suite, then call a target or import saved outputs.' }}</p><Button v-if="canEdit && !experimentSearch && !experimentStatus" @click="modal = 'launch'">Launch experiment</Button></div></section>
  <template v-if="['datasets','targets','evaluators'].includes(page)"><div class="table-toolbar standalone"><input v-model="resourceSearch" aria-label="Search resources" placeholder="Search by name…"/></div>
    <section v-for="kind in (page === 'evaluators' ? ['evaluator','suite'] : [page === 'datasets' ? 'dataset' : 'target'])" :key="kind" class="panel"><div class="panel-header"><h2>{{ kind === 'suite' ? 'Evaluation suites' : kind === 'evaluator' ? 'Evaluator library' : kind === 'dataset' ? 'Versioned datasets' : 'Targets' }} <span class="count">{{ resources(kind).length }}</span></h2><Button v-if="canEdit && kind === 'suite'" variant="outline" size="sm" @click="openCreate('suite')">New suite</Button></div><table v-if="visibleResources(kind).length"><thead><tr><th>Name</th><th>Latest version</th><th>Configuration</th><th>Actions</th></tr></thead><tbody><tr v-for="r in visibleResources(kind)" :key="r.id"><td><button class="strong-link" @click="openEdit(r)">{{ r.name }}</button></td><td><span class="version-badge">v{{ r.versions[0]?.number }}</span> <small>{{ r.versions.length }} saved</small></td><td class="muted"><span v-if="kind === 'dataset'">{{ r.versions[0]?.config.held_out ? 'Held out' : 'Development' }}</span><span v-else-if="kind === 'target'" class="mono">{{ (r.versions[0]?.config.kind === 'openai' ? r.versions[0]?.config.model : r.versions[0]?.config.endpoint) }}</span><span v-else-if="kind === 'evaluator'">{{ human(r.versions[0]?.config.kind || '') }} · {{ metricLabel(r.versions[0]?.config.metric_key || '') }}</span><span v-else>{{ r.versions[0]?.config.evaluator_version_ids.length }} evaluators</span></td><td><div class="inline-actions"><Button variant="outline" size="sm" @click="openEdit(r)">{{ canEdit ? 'Edit versions' : 'View versions' }}</Button><a v-if="kind === 'dataset'" :href="`/api/versions/${r.versions[0]?.id}/jsonl`" aria-label="Export JSONL"><Download :size="17"/></a><Button v-if="canEdit && kind === 'target'" variant="outline" size="sm" @click="selectedVersion = r.versions[0]!.id; modal = 'test'; testResult = null">Test</Button></div></td></tr></tbody></table><div v-else class="empty-state"><h3>{{ resourceSearch ? 'No matching resources' : `No ${kind} configured` }}</h3><Button v-if="canEdit && !resourceSearch" @click="openCreate(kind)">Create {{ kind }}</Button></div></section>
  </template>
  <template v-if="page === 'results' && experiment.data.value">
    <div class="experiment-toolbar"><Status :value="experiment.data.value.status"/><span>{{ experiment.data.value.parent_id ? 'Rescored outputs' : experiment.data.value.mode === 'imported' ? 'Imported outputs' : 'Live target' }} · {{ experiment.data.value.summary.total }} cases · {{ resultMetricCount }} criteria</span><div class="spacer"></div><Button v-if="canEdit && ['queued','running'].includes(experiment.data.value.status)" variant="outline" @click="action(() => post(`/experiments/${experimentId}/cancel`), 'Cancellation requested')" :disabled="busy">Cancel</Button><Button v-if="canEdit && ['failed','partially_failed'].includes(experiment.data.value.status)" variant="outline" @click="action(() => post(`/experiments/${experimentId}/retry`), 'Failed work queued')">Retry failed work</Button><RouterLink :to="`/projects/${projectId}/compare?candidate=${experimentId}`" class="text-link">Compare run <ArrowRight :size="15"/></RouterLink></div>
    <div v-if="['queued', 'running'].includes(experiment.data.value.status)" class="run-progress" role="status"><div><strong>{{ progress.done }} / {{ progress.total }} executions finished</strong><span>Updating results…</span></div><progress :value="progress.done" :max="progress.total || 1" aria-label="Experiment progress"/></div>
    <div class="stat-grid"><article class="stat-card"><span>{{ experiment.data.value.repetitions > 1 ? 'Case runs passed' : 'Cases passed' }}</span><strong>{{ passingCases }} / {{ experiment.data.value.summary.total }}</strong><small>Passed every criterion</small></article><article class="stat-card"><span>Evaluation coverage</span><strong>{{ percent(resultCoverage) }}</strong><small>Scored criteria / planned criteria</small></article><article class="stat-card"><span>Target errors</span><strong>{{ experiment.data.value.summary.target_errors }}</strong><small v-if="experiment.data.value.summary.target_errors">Open a case for details</small></article><article class="stat-card"><span title="95th percentile, nearest-rank method">P95 response time</span><strong class="smaller">{{ ms(experiment.data.value.summary.target_latency_ms.p95) }}</strong><small>{{ experiment.data.value.summary.target_latency_ms.n }} measured responses</small></article></div>
    <section class="panel"><div class="panel-header"><h2>Evaluation criteria</h2><RouterLink :to="`/projects/${projectId}/gates?experiment=${experimentId}`" class="text-link">Release checks <ArrowRight :size="15"/></RouterLink></div><table><thead><tr><th>Criterion</th><th>Mean score</th><th>Passed / failed</th><th>Coverage</th><template v-if="hasScoreIssues"><th>N/A</th><th>Errors</th><th>Missing</th></template></tr></thead><tbody><tr v-for="(m,key) in experiment.data.value.summary.metrics" :key="key"><td :title="String(key)">{{ metricLabel(String(key)) }}</td><td><strong>{{ percent(m.mean) }}</strong></td><td>{{ m.passed }} / {{ m.failed }}</td><td>{{ m.scored }} / {{ m.denominator }}</td><template v-if="hasScoreIssues"><td>{{ m.not_applicable }}</td><td>{{ m.errors }}</td><td>{{ m.missing }}</td></template></tr></tbody></table></section>
    <template v-for="(m,key) in experiment.data.value.summary.metrics" :key="String(key)"><section v-if="m.classification" class="panel pad"><h3>{{ key }} · classification metrics</h3><JsonView :value="m.classification"/></section></template>
    <section class="panel case-results"><div class="panel-header"><h2>Case results</h2><select v-model="filter" aria-label="Filter case results"><option value="all">All cases</option><option value="failing">Failing scores</option><option value="errors">Execution errors</option></select></div><table v-if="filteredRows.length"><thead><tr><th>Case</th><th>Execution</th><th>Criteria</th><th>Response time</th><th>Review</th></tr></thead><tbody><tr v-for="row in filteredRows" :key="row.id"><td><RouterLink :to="`/cases/${row.id}`" class="strong-link" :aria-label="`${caseLabel(row.case, row.case_id)} (${row.case_id})`">{{ caseLabel(row.case, row.case_id) }}</RouterLink><small v-if="experiment.data.value.repetitions > 1" class="block">Repetition {{ row.replicate + 1 }}</small></td><td><Status :value="row.status"/></td><td><CriteriaSummary :results="row.results" :expected="resultMetricCount"/></td><td>{{ ms(row.target_latency_ms) }}</td><td>{{ row.reviews.length ? 'Reviewed' : 'Unreviewed' }}</td></tr></tbody></table><div v-else class="empty-state"><h3>No cases match this filter</h3><button class="text-link" @click="filter = 'all'">Show all cases</button></div></section>
    <div class="two-col result-secondary"><section class="panel pad"><h3>Human review</h3><p v-if="!experiment.data.value.calibration.reviewed_decisions">No human assessments yet.</p><p v-else>{{ experiment.data.value.calibration.reviewed_decisions }} decisions · {{ percent(experiment.data.value.calibration.agreement) }} agreement · {{ experiment.data.value.calibration.disagreements.length }} disagreements</p><RouterLink :to="`/projects/${projectId}/reviews`" class="text-link">Review cases <ArrowRight :size="15"/></RouterLink></section><section class="panel pad"><h3>Export results</h3><div class="inline-actions"><a class="text-link" :href="`/api/experiments/${experimentId}/report?format=json&metric=${Object.keys(experiment.data.value.summary.metrics)[0] || ''}`"><Download :size="15"/>JSON report</a><a class="text-link" :href="`/api/experiments/${experimentId}/report?format=junit&metric=${Object.keys(experiment.data.value.summary.metrics)[0] || ''}`">JUnit report</a></div></section></div>
    <details class="panel pad"><summary>Run details & actions</summary><dl class="run-details"><dt>Run ID</dt><dd class="mono">{{ experimentId }}</dd><dt>Execution</dt><dd>{{ experiment.data.value.concurrency }} concurrent · {{ experiment.data.value.repetitions }} repetition(s)</dd><dt>Target cost</dt><dd>{{ experiment.data.value.summary.target_cost.total_usd == null ? 'Not reported by the provider' : `$${experiment.data.value.summary.target_cost.total_usd.toFixed(4)}` }}</dd></dl><Button v-if="canEdit && experiment.data.value.status === 'completed'" variant="outline" :disabled="busy" @click="action(() => post(`/projects/${projectId}/baselines`, { experiment_id: experimentId }), 'Baseline pinned')"><Pin :size="14"/>Pin baseline</Button><div class="rescore-controls"><h3>Rescore saved outputs</h3><p>Reuse outputs with another evaluation suite.<template v-if="launchJudges.length"> AI reviewers incur provider charges.</template></p><label>Evaluation suite<select v-model="suiteId"><option v-for="v in versions('suite')" :key="v.id" :value="v.id">{{ v.label }}</option></select></label><Button variant="outline" :disabled="busy || ['queued','running'].includes(experiment.data.value.status)" v-if="canEdit" @click="rescore"><RotateCcw :size="14"/>Rescore outputs</Button></div></details>
  </template>
  <template v-if="page === 'case' && execution.data.value">
    <div class="experiment-toolbar"><Status :value="execution.data.value.status"/><span>Repetition {{ execution.data.value.replicate + 1 }}</span><span>Target {{ ms(execution.data.value.target_latency_ms) }}</span><span>Evaluation {{ ms(execution.data.value.evaluation_latency_ms) }}</span><span v-if="execution.data.value.late_completion" class="warning-chip">Finished after cancellation</span></div><div v-if="execution.data.value.target_error" class="error">{{ execution.data.value.target_error }}</div>
    <div class="two-col"><section class="panel"><div class="panel-header"><h2>Input</h2></div><JsonView :value="execution.data.value.case.input"/></section><section class="panel"><div class="panel-header"><h2>Actual output</h2></div><JsonView :value="execution.data.value.output" :missing="!execution.data.value.output_present"/></section><section class="panel"><div class="panel-header"><h2>Expected output</h2></div><JsonView :value="execution.data.value.case.expected" :missing="!('expected' in execution.data.value.case)"/></section><section class="panel"><div class="panel-header"><h2>Source context</h2></div><template v-if="typeof execution.data.value.case.context?.reference_passage === 'string'"><p class="source-passage">{{ execution.data.value.case.context.reference_passage }}</p><details><summary>Source & annotations</summary><JsonView :value="execution.data.value.case.context"/></details></template><JsonView v-else :value="execution.data.value.case.context"/><p v-if="execution.data.value.case.acceptance_criteria" class="source-passage">{{ execution.data.value.case.acceptance_criteria }}</p></section></div>
    <section class="panel"><div class="panel-header"><h2>Evaluator evidence</h2></div><div v-for="r in execution.data.value.results" :key="r.metric_key" class="evaluator-row"><div><strong :title="r.metric_key">{{ metricLabel(r.metric_key) }}</strong><p>{{ r.explanation }}</p><small v-if="r.evidence.length">{{ r.evidence.join(', ') }}</small></div><Status :value="r.status !== 'scored' ? r.status : r.passed == null ? 'scored' : r.passed ? 'pass' : 'fail'"/></div></section>
    <section class="panel pad"><h3>Human assessment</h3><p>Your review is saved alongside the automated result.</p><form v-if="canEdit" @submit.prevent="saveReview"><div class="form-grid"><label>Criterion<select v-model="reviewMetric"><option v-for="r in execution.data.value.results" :key="r.metric_key" :value="r.metric_key">{{ metricLabel(r.metric_key) }}</option></select></label><label>Human decision<select v-model="reviewPassed"><option :value="true">Pass</option><option :value="false">Fail</option></select></label></div><label>Assessment note<textarea v-model="reviewNote" required placeholder="Explain the decision using observable evidence."/></label><Button type="submit" :disabled="busy || !reviewMetric">Save human assessment</Button></form><div v-for="r in execution.data.value.reviews" :key="r.id" class="review-note"><Status :value="r.passed ? 'pass' : 'fail'"/><p>{{ r.note }}</p><small>{{ new Date(r.created_at).toLocaleString('en-US') }}</small></div></section>
    <details class="panel pad"><summary>Execution details</summary><dl class="run-details"><dt>Case ID</dt><dd class="mono">{{ execution.data.value.case_id }}</dd></dl><h3 v-if="execution.data.value.trace">Observable tool-call trace</h3><JsonView v-if="execution.data.value.trace" :value="execution.data.value.trace"/><h3>Telemetry & provenance</h3><JsonView :value="execution.data.value.metadata"/><h3>Attempt history</h3><table><thead><tr><th>Phase</th><th>Attempt</th><th>Outcome</th><th>Error</th></tr></thead><tbody><tr v-for="a in execution.data.value.attempts" :key="a.id"><td>{{ a.phase }}</td><td>{{ a.number }}</td><td><Status :value="a.status"/></td><td>{{ a.error || '—' }}</td></tr></tbody></table></details>
  </template>
  <section v-if="page === 'reviews'" class="panel"><div class="table-toolbar"><input v-model="reviewSearch" aria-label="Search review cases" placeholder="Search cases or experiments…"/><small>Cases from the 10 most recent completed runs.</small></div><div class="panel-header"><h2>Calibration queue <span class="count">{{ displayReviews.length }}</span></h2><label class="check-label"><input v-model="onlyUnreviewed" type="checkbox"/>Unreviewed only</label></div><table v-if="displayReviews.length"><thead><tr><th>Case</th><th>Experiment</th><th>Automated criteria</th><th>Human assessments</th><th></th></tr></thead><tbody><tr v-for="row in displayReviews" :key="row.id"><td :title="row.case_id">{{ caseLabel(row.case, row.case_id) }}<small class="block">Repetition {{ row.replicate + 1 }}</small></td><td>{{ row.experiment_name }}</td><td><CriteriaSummary :results="row.results"/></td><td>{{ row.reviews.length }}</td><td><RouterLink :to="`/cases/${row.id}`" class="text-link">Review <ArrowRight :size="15"/></RouterLink></td></tr></tbody></table><div v-else class="empty-state"><Check/><h3>No cases waiting for review</h3><p>Completed experiments populate this queue.</p></div></section>
  <div v-if="page === 'gates'" class="release-layout"><section class="panel pad release-check"><h2>Check an experiment</h2><p>Apply the saved policy to a completed run.</p><label>Experiment<select v-model="gateExperiment" aria-label="Experiment"><option v-for="e in project.data.value?.experiments" :key="e.id" :value="e.id">{{ e.name }}</option></select></label><label>Regression criterion<select v-model="metric" aria-label="Regression criterion"><option v-for="m in gateMetrics" :key="m" :value="m">{{ metricLabel(m) }}</option></select><small>All policy thresholds are checked as well.</small></label><p v-if="gateCheck.isFetching.value" role="status">Checking release criteria…</p><div v-else-if="gateCheck.error.value" class="error" role="alert">{{ gateCheck.error.value.message }} <button class="text-link" @click="gateCheck.refetch()">Try again</button></div><div v-else-if="gateResult" class="gate-result" :class="gateResult.passed ? 'pass' : 'fail'" role="status"><h3>{{ gateResult.passed ? 'Checks passed' : gateResult.exit_code === 2 ? 'Unable to verify' : 'Changes needed' }}</h3><p>{{ gateResult.passed ? 'This run meets the saved release policy.' : gateResult.exit_code === 2 ? 'Resolve the errors below, then check again.' : 'This run does not meet the saved release policy.' }}</p><ul v-if="!gateResult.passed"><li v-for="reason in [...gateResult.quality_failures,...gateResult.infrastructure_errors]" :key="reason">{{ releaseReason(reason) }}</li></ul></div><p v-else-if="gateExperiment && !gateReady">Results will be available when the run finishes.</p><p v-else>Select an experiment to check its results.</p><div class="inline-actions report-actions"><Button variant="outline" :disabled="!gateReady || gateCheck.isFetching.value" @click="gateCheck.refetch()"><ShieldCheck :size="16"/>Check again</Button><a v-if="gateReady" class="text-link" :href="`/api/experiments/${gateExperiment}/report?format=json&metric=${metric}`"><Download :size="15"/>Download report</a></div><details v-if="gateReady"><summary>CI integration & exports</summary><pre class="json-view">evaldock gate {{ gateExperiment }} --metric {{ metric }}</pre><p v-if="gateResult">Exit code {{ gateResult.exit_code }}</p><div class="inline-actions"><a class="text-link" :href="`/api/experiments/${gateExperiment}/report?format=junit&metric=${metric}`">JUnit report</a><Button v-if="canEdit" variant="outline" size="sm" @click="action(() => post(`/experiments/${gateExperiment}/artifacts?metric=${metric}`), 'Report snapshot saved')">Save snapshot</Button></div></details></section><section v-if="gateConfig.data.value" class="panel pad release-policy"><h2>Release policy</h2><p>Every threshold must pass.</p><dl class="policy-summary"><div><dt>Minimum coverage</dt><dd>{{ percent(gateConfig.data.value.min_coverage) }}</dd></div><div><dt>Allowed regressions</dt><dd>{{ gateConfig.data.value.max_regressions }}</dd></div><div><dt>Allowed target errors</dt><dd>{{ percent(gateConfig.data.value.max_target_error_rate) }}</dd></div><div v-if="gateConfig.data.value.critical_tag"><dt>Must-pass tag</dt><dd>{{ gateConfig.data.value.critical_tag }}</dd></div><div v-if="gateConfig.data.value.max_p95_latency_ms != null"><dt>P95 response limit</dt><dd>{{ ms(gateConfig.data.value.max_p95_latency_ms) }}</dd></div></dl><table v-if="Object.keys(gateConfig.data.value.min_accuracy || {}).length"><thead><tr><th>Criterion</th><th>Minimum</th></tr></thead><tbody><tr v-for="(threshold,key) in gateConfig.data.value.min_accuracy" :key="key"><td>{{ metricLabel(String(key)) }}</td><td>{{ percent(Number(threshold)) }}</td></tr></tbody></table><p v-else>No minimum scores configured.</p><details class="policy-editor"><summary>{{ canEdit ? 'Edit release policy' : 'View full policy' }}</summary><GateEditor :project-id="projectId" :config="gateConfig.data.value" :metrics="metricKeys" :readonly="!canEdit" @saved="gateConfig.refetch()"/></details></section></div>
  <template v-if="page === 'settings'"><div class="two-col"><section class="panel pad"><template v-if="openaiCredential"><h3>OpenAI API key</h3><p>{{ openaiCredential.configured ? 'Configured' : 'Not configured' }}</p><p v-if="openaiCredential.source === 'environment' && !openaiCredential.configured">Set <code>OPENAI_API_KEY</code> in the server <code>.env</code>.</p><form v-if="canEdit && openaiCredential.source !== 'environment'" @submit.prevent="saveOpenaiKey"><label>API key<input v-model="openaiValue" type="password" autocomplete="new-password" placeholder="sk-…" required/></label><Button type="submit" :disabled="busy || !openaiValue.trim()">Save API key</Button></form></template><details v-if="showServiceCredentials" :open="!openaiCredential"><summary>Service API keys</summary><p>Keys used by targets and AI evaluators.</p><div v-for="c in serviceCredentials" :key="c.id" class="credential-row"><strong>{{ c.name }}</strong><span>{{ c.value }}</span></div><form v-if="canEdit" @submit.prevent="createSecret"><label>Service name<input v-model="secretName" required/></label><label>API key<input v-model="secretValue" type="password" autocomplete="new-password" required/></label><Button type="submit" :disabled="busy">Save key</Button></form></details></section><section class="panel pad"><h3>Workspace API tokens</h3><form @submit.prevent="createToken"><label>Token name<input v-model="tokenName" required/></label><div class="form-grid"><label>Token access<select v-model="tokenScope"><option value="read">Read only</option><option v-if="canEdit" value="write">Read & write</option></select></label><label>Expires in (days)<input v-model.number="tokenDays" type="number" min="1" max="365" required/></label></div><Button type="submit" :disabled="busy">Create token</Button></form><div v-if="newToken" class="token-reveal"><strong>Copy this token before leaving.</strong><pre class="json-view">{{ newToken }}</pre><Button type="button" variant="outline" size="sm" @click="copyToken">{{ copied ? 'Copied' : 'Copy token' }}</Button><Button type="button" variant="ghost" size="sm" @click="newToken = ''">Hide token</Button></div><div v-for="t in workspaceTokens.filter(t => !t.revoked)" :key="t.id" class="credential-row"><span>{{ t.name }} · {{ t.scopes.join(', ') }}</span><Button size="sm" variant="outline" @click="action(() => api(`/tokens/${t.id}`, { method: 'DELETE' }), 'Token revoked')">Revoke</Button></div><details v-if="workspaceTokens.some(t => t.revoked)" class="revoked-tokens"><summary>Revoked tokens</summary><div v-for="t in workspaceTokens.filter(t => t.revoked)" :key="t.id" class="credential-row"><span>{{ t.name }}</span><small>{{ t.scopes.join(', ') }}</small></div></details></section></div><details class="panel pad settings-details"><summary>Workspace members</summary><table><thead><tr><th>Member</th><th>Email</th><th>Role</th></tr></thead><tbody><tr v-for="m in settingsData.data.value?.members" :key="m.id"><td>{{ m.name }}</td><td>{{ m.email }}</td><td>{{ m.role }}</td></tr></tbody></table><form v-if="canAdmin" class="member-form" @submit.prevent="action(async () => { await post(`/workspaces/${project.data.value?.workspace_id}/members`, member); member.password = '' }, 'Workspace member added')"><label>Name<input v-model="member.name" required/></label><label>Email<input v-model="member.email" type="email" required/></label><label>Initial password<input v-model="member.password" type="password" minlength="12" required/></label><label>Role<select v-model="member.role"><option>viewer</option><option>editor</option><option>owner</option></select></label><Button type="submit">Add member</Button></form></details><details class="panel settings-details"><summary>Activity</summary><table><thead><tr><th>Action</th><th>Time</th><th>Record</th></tr></thead><tbody><tr v-for="a in settingsData.data.value?.audit" :key="a.id"><td>{{ a.action }}</td><td>{{ new Date(a.created_at).toLocaleString('en-US') }}</td><td class="mono">{{ JSON.stringify(a.detail) }}</td></tr></tbody></table></details><details v-if="project.data.value?.description" class="panel pad settings-details"><summary>Project notes</summary><p>{{ project.data.value.description }}</p></details><Button v-if="canEdit" variant="outline" @click="modal = 'project'; formName = ''">Create another project</Button></template>
  <ResourceEditor v-if="modal === 'resource' && project.data.value" :project="project.data.value" :kind="editorKind" :resource="selectedResource" :readonly="!canEdit" @close="modal = ''" @saved="resourceSaved"/><ModalFrame v-if="modal && modal !== 'resource'" :title="modal === 'launch' ? 'Launch experiment' : modal === 'test' ? 'Test target connection' : 'New project'" :busy="busy" @close="closeModal"><div class="modal-body"><div v-if="error" class="error" role="alert">{{ error }}</div>
    <form v-if="modal === 'launch'" @submit.prevent="launchExperiment"><div v-if="launchMissing" class="warning-strip">{{ launchMissing }}</div><div v-if="launchCredentialIssue" class="warning-strip">{{ launchCredentialIssue }} <RouterLink v-if="launchCredentialIssue.includes('Settings')" :to="`/projects/${projectId}/settings`" @click="modal = ''" class="text-link">Settings</RouterLink></div><div class="launch-summary"><span class="eyebrow">RUN SUMMARY</span><strong>{{ plannedCalls }} planned executions</strong><small>{{ launchDataset.data.value?.cases.length || 0 }} cases × {{ repetitions }} repetition(s) · {{ concurrency }} concurrent</small><small v-if="launchJudges.length">{{ plannedCalls * launchJudges.length }} AI reviews · provider usage is billed to your account</small><small>Main baseline: {{ baselineLabel }}</small></div><label>Experiment name<input v-model="launchName" placeholder="e.g. Prompt v3 · candidate"/></label><label>Dataset version<select v-model="datasetId" required><option v-for="v in versions('dataset')" :key="v.id" :value="v.id">{{ v.label }}</option></select></label><label>Execution mode<select v-model="launchMode"><option value="http">Run target</option><option value="imported">Imported outputs</option></select></label><label v-if="launchMode === 'http'">Target version<select v-model="targetId" required><option v-for="v in versions('target')" :key="v.id" :value="v.id">{{ v.label }}</option></select></label><ImportedOutputEditor v-else v-model="imported" :cases="launchDataset.data.value?.cases || []" :repetitions="Number(repetitions)" @validity="launchValid = $event"/><label>Evaluation suite<select v-model="suiteId" required><option v-for="v in versions('suite')" :key="v.id" :value="v.id">{{ v.label }}</option></select></label><div class="two-col"><label>Repetitions<input v-model="repetitions" type="number" min="1" max="20" required/></label><label>Concurrency<input v-model="concurrency" type="number" min="1" max="16" required/></label></div><label v-if="launchMode === 'http'">Optional target call budget<input v-model="budget" type="number" min="1" placeholder="Unlimited"/></label><p class="muted">Only case input is sent to the target.</p><Button type="submit" :disabled="busy || !!launchMissing || !!launchCredentialIssue || !launchValid"><Play :size="15"/>{{ busy ? 'Launching…' : 'Launch experiment' }}</Button></form>
    <form v-else-if="modal === 'test'" @submit.prevent="action(async () => { testResult = await post(`/targets/${selectedVersion}/test`, { input: testJson }) }, 'Connection test completed')"><p>This sends one real request to the configured test endpoint.</p><JsonField v-model="testJson" label="Target input JSON" :rows="10" @validity="testValid = $event"/><Button type="submit" :disabled="busy || !testValid">Send test request</Button><JsonView v-if="testResult" :value="testResult"/></form>
    <form v-else @submit.prevent="action(async () => { const p = await post<Project>('/projects', { name: formName, workspace_id: project.data.value?.workspace_id }); modal = ''; router.push(`/projects/${p.id}/overview`) }, 'Project created')"><label>Project name<input v-model="formName" required/></label><Button type="submit">Create project</Button></form>
  </div></ModalFrame>
</main>
</template>
